// Des: Tests for redaction, purge and folder lock-down
// Flo: emails, phones, ids, names removed > normal words kept > purge drops old rows only > lock-down runs on a scratch folder
// I/O: text samples + scratch db (no leaks)
// Run: zig build test -Dfile=ru-safe-priv-test.zig
// ===================================================================
const std = @import("std"); const priv = @import("ru-safe-priv.zig"); const task = @import("ru-task-runn.zig"); const stat = @import("st-stat-main.zig"); const pg = @import("ru-page-snap.zig"); const pace = @import("ru-huma-pace.zig");
const allo = std.testing.allocator;
fn red(txt: []const u8) ![]u8 { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const got = try priv.redact(aren.allocator(), txt); return allo.dupe(u8, got); }
test "emails, phones and long ids are removed" { const out = try red("Mail ann.lee@example.com or call +84 912 345 678 id 100012345678 ok"); defer allo.free(out); try std.testing.expect(std.mem.find(u8, out, "@") == null); try std.testing.expect(std.mem.find(u8, out, "912") == null); try std.testing.expect(std.mem.find(u8, out, "100012345678") == null); try std.testing.expect(std.mem.find(u8, out, "[email]") != null); try std.testing.expect(std.mem.find(u8, out, "[num]") != null); }
test "two words after by/from/bởi are names and removed; whitespace layout kept" { const out = try red("Comment by Ann Lee\nIs this available?\nReply from Bob Tran now"); defer allo.free(out); try std.testing.expectEqualStrings("Comment by [name] [name]\nIs this available?\nReply from [name] [name] now", out); }
test "plain text and short numbers stay" { const out = try red("Red bike 26 inch, price 2000 ok"); defer allo.free(out); try std.testing.expectEqualStrings("Red bike 26 inch, price 2000 ok", out); const vi = try red("Xe đạp Thống Nhất còn mới"); defer allo.free(vi); try std.testing.expectEqualStrings("Xe đạp Thống Nhất còn mới", vi); }
test "purge deletes only rows older than the keep window" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const pth = try std.fmt.allocPrintSentinel(allo, ".zig-cache/tmp/{s}/fb.db", .{tmpz.sub_path}, 0); defer allo.free(pth); var sto = try stat.Stat.open(allo, pth); defer sto.close(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var page: pg.Page = undefined; var rng = pace.Rng.init(1); const dayz: i64 = 86400000; var cx: task.Ctx = .{ .gpaz = allo, .aren = aren.allocator(), .iozz = std.testing.io, .conf = .{}, .store = &sto, .mode = .dry, .page = &page, .rng = &rng, .base = "", .now_fix = 100 * dayz }; try sto.logAdd("post", "old", true, 10 * dayz); try sto.logAdd("post", "new", true, 99 * dayz); try sto.actAdd("post", "k", 10 * dayz); try std.testing.expectEqual(@as(i64, 2), try priv.purge(&cx)); const rows = try sto.logRecent(aren.allocator(), 10); try std.testing.expectEqual(@as(usize, 1), rows.len); try std.testing.expectEqualStrings("new", rows[0].what); }
test "lock-down fails quietly on a missing folder and builds the Windows grant" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const grant = try priv.grantFor(aren.allocator(), "nobody-zz"); try std.testing.expect(std.mem.endsWith(u8, grant, ":(OI)(CI)F")); try std.testing.expect(!priv.lockDown(allo, std.testing.io, "zz-no-such-dir-zz", grant)); }
test "Windows lock: owner is a SID, a plain name is refused, a SID grant keeps the folder usable" { if (@import("builtin").os.tag != .windows) return error.SkipZigTest; const root = std.testing.environ.getAlloc(allo, "SystemRoot") catch try allo.dupe(u8, ""); defer allo.free(root); const ownr = try priv.ownerId(allo, std.testing.io, root); defer allo.free(ownr); try std.testing.expect(std.mem.startsWith(u8, ownr, "*S-1-5-")); var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); try std.testing.expect(!priv.lockDown(allo, std.testing.io, dirz, "somename:(OI)(CI)F")); try tmpz.dir.writeFile(std.testing.io, .{ .sub_path = "a.txt", .data = "1" }); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const grant = try priv.grantFor(aren.allocator(), ownr); try std.testing.expect(priv.lockDown(allo, std.testing.io, dirz, grant)); try tmpz.dir.writeFile(std.testing.io, .{ .sub_path = "b.txt", .data = "2" }); }
